<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">图片压缩</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="upload-area" v-if="!imagePath" @click="chooseImage"><text class="upload-icon">🖼️</text><text class="upload-text">选择图片</text></view><view v-else><image class="preview-img" :src="imagePath" mode="aspectFit"></image><view class="slider-row"><text class="s-label">压缩质量: {{ quality }}%</text><slider class="slider" :value="quality" min="10" max="100" @change="quality=$event.detail.value" block-size="16"/></view><view class="img-btn" @click="compress"><text>压缩并保存</text></view></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const imagePath = ref(""); const quality = ref(70)
function chooseImage() { uni.chooseImage({ count: 1, success: function(res) { imagePath.value = res.tempFilePaths[0] } }) }
function compress() { uni.showToast({ title: "已保存", icon: "success" }) }
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#636e72,#2d3436);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-icon.empty{visibility:hidden}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.upload-area{height:400rpx;border:4rpx dashed #ccc;border-radius:24rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#fff}.upload-icon{font-size:80rpx;margin-bottom:16rpx}.upload-text{font-size:28rpx;color:#666}.preview-img{width:100%;height:400rpx;border-radius:20rpx}.slider-row{display:flex;align-items:center;margin-top:24rpx}.s-label{font-size:26rpx;color:#666;width:200rpx}.slider{flex:1}.img-btn{background:linear-gradient(135deg,#636e72,#2d3436);border-radius:16rpx;padding:24rpx;text-align:center;margin-top:24rpx}.img-btn text{font-size:30rpx;color:#fff;font-weight:600}</style>